import json

# Let's implement a working solution by mapping segments correctly

def find_segments(grid, right_start=6, right_end=11):
    """Find all segments of non-zero blocks in the right portion of the grid"""
    rows = len(grid)

    # For each color, find rows that have that color
    color_rows = {}
    for r in range(rows):
        for c in range(right_start, right_end + 1):
            v = grid[r][c]
            if v != 0:
                if v not in color_rows:
                    color_rows[v] = []
                color_rows[v].append(r)

    # Sort each color's rows to get contiguous segments
    segments = []
    for color, rows in color_rows.items():
        rows_sorted = sorted(rows)
        # Find contiguous segments
        seg_start = rows_sorted[0]
        seg_last = rows_sorted[0]
        for r in rows_sorted[1:]:
            if r == seg_last + 1:
                seg_last = r
            else:
                # New segment
                segments.append(color, seg_start, seg_last)
                seg_start = r
                seg_last = r
        segments.append(color, seg_start, seg_last)

    return segments

